title = #{title}, content = #{content}, status = #{status}, updated_at = NOW()
WHERE post_id = #{postId}

	UPDATE  posts
	   SET   title      = #{title}
   			,updated_at = NOW()
	 WHERE  post_id    	= #{postId}

	UPDATE  posts
	   SET  category_id    = #{categoryId}
	   	    ,parent_post_id = #{parentPostId}
	   		,sort_seq       = #{sortSeq}
   			,updated_at 	= NOW()
	 WHERE  post_id    		= #{postId}

mapper.select:
SELECT post_id ,title ,author_id ,sort_seq ,view_count ,updated_at FROM posts WHERE del_yn = 'N'
AND parent_post_id = #{parentPostId}
AND parent_post_id IS NULL AND category_id = #{categoryId}
ORDER BY sort_seq ASC

WITH RECURSIVE parent_categories AS ( SELECT * FROM categories WHERE category_id = #{categoryId}
UNION ALL
SELECT c.* FROM categories c INNER JOIN parent_categories pc ON c.parent_category_id = pc.category_id ) SELECT p.post_id, p.parent_post_id, p.category_id, p.sort_seq, p.author_id, p.title FROM parent_categories pc LEFT OUTER JOIN posts p ON pc.category_id = p.category_id WHERE p.post_id IS NOT NULL AND p.del_yn = 'N' ORDER BY p.category_id, p.sort_seq;

